using AcxiomCRM.Backend.Data; using AcxiomCRM.Backend.Models; using AcxiomCRM.Backend.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Backend.Controllers;
[ApiController,Route("api/opportunities"),Authorize]
public class OpportunitiesController(CrmDbContext db):ControllerBase
{
 [HttpGet] public async Task<IActionResult> Get(){var q=db.Opportunities.AsQueryable(); if(User.IsInRole("Sales Executive"))q=q.Where(x=>x.Assigned==User.Identity!.Name); return Ok(await q.OrderByDescending(x=>x.Id).ToListAsync());}
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var x=await db.Opportunities.FindAsync(id);return x is null?NotFound():Ok(x);}
 [HttpPost] public async Task<IActionResult> Create(Opportunity x){if(!ModelState.IsValid)return ValidationProblem(ModelState); if(x.Amount<=0)return BadRequest(new{message="Opportunity amount must be greater than zero."}); if(x.Probability<0||x.Probability>100)return BadRequest(new{message="Probability must be between 0 and 100."}); if(x.Status=="Open"&&x.CloseDate.Date<DateTime.UtcNow.Date)return BadRequest(new{message="Expected close date cannot be in the past."}); if(x.Stage is not ("Qualification" or "Proposal" or "Negotiation" or "Won" or "Lost"))return BadRequest(new{message="Invalid opportunity stage."}); db.Opportunities.Add(x);await db.SaveChangesAsync();await AuditService.WriteAsync(db,User,HttpContext,"Created","Opportunity",x.Name);return CreatedAtAction(nameof(Get),new{id=x.Id},x);}
 [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,Opportunity input){if(id!=input.Id)return BadRequest();if(!ModelState.IsValid)return ValidationProblem(ModelState);if(input.Amount<=0||input.Probability<0||input.Probability>100)return BadRequest(new{message="Amount must be positive and probability must be between 0 and 100."});if(input.Status=="Open"&&input.CloseDate.Date<DateTime.UtcNow.Date)return BadRequest(new{message="Expected close date cannot be in the past."});var x=await db.Opportunities.FindAsync(id);if(x is null)return NotFound();db.Entry(x).CurrentValues.SetValues(input);await db.SaveChangesAsync();await AuditService.WriteAsync(db,User,HttpContext,"Updated","Opportunity",x.Name);return Ok(x);}
 [Authorize(Roles="Admin,Manager"),HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var x=await db.Opportunities.FindAsync(id);if(x is null)return NotFound();db.Opportunities.Remove(x);await db.SaveChangesAsync();await AuditService.WriteAsync(db,User,HttpContext,"Deleted","Opportunity",x.Name);return NoContent();}
}
